package com.example.sample.feature.${feature}

import androidx.compose.foundation.layout.Arrangement
import androidx.compose.foundation.layout.Column
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.padding
import androidx.compose.material3.CircularProgressIndicator
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.runtime.getValue
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.tooling.preview.Preview
import androidx.compose.ui.unit.dp
import androidx.lifecycle.compose.collectAsStateWithLifecycle
import androidx.lifecycle.viewmodel.compose.viewModel
import com.example.sample.ui.component.AppButton
import com.example.sample.ui.component.AppButtonEmphasis
import com.example.sample.ui.core.UiState
import com.example.sample.ui.preview.PreviewRoot

/** The ${feature} screen, wired to its [${feature}ViewModel]. */
@Composable
internal fun ${feature}Screen(
    onNavigateUp: () -> Unit,
    modifier: Modifier = Modifier,
    viewModel: ${feature}ViewModel = viewModel(),
) {
    val uiState by viewModel.uiState.collectAsStateWithLifecycle()
    ${feature}Screen(
        uiState = uiState,
        onRefresh = viewModel::refresh,
        onNavigateUp = onNavigateUp,
        modifier = modifier,
    )
}

/** The ${feature} screen as a function of its state. */
@Composable
internal fun ${feature}Screen(
    uiState: UiState<${feature}Content>,
    onRefresh: () -> Unit,
    onNavigateUp: () -> Unit,
    modifier: Modifier = Modifier,
) {
    Column(
        modifier = modifier
            .fillMaxSize()
            .padding(24.dp),
        verticalArrangement = Arrangement.spacedBy(16.dp, Alignment.CenterVertically),
        horizontalAlignment = Alignment.CenterHorizontally,
    ) {
        when (uiState) {
            UiState.Loading -> CircularProgressIndicator()

            is UiState.Content -> {
                Text(
                    text = uiState.value.userName,
                    style = MaterialTheme.typography.headlineSmall,
                )
                AppButton(text = "Reload", onClick = onRefresh)
            }

            is UiState.Error -> Text(
                text = uiState.message,
                style = MaterialTheme.typography.bodyMedium,
                color = MaterialTheme.colorScheme.error,
            )
        }

        AppButton(
            text = "Back",
            onClick = onNavigateUp,
            emphasis = AppButtonEmphasis.Outlined,
        )
    }
}

@Preview(showBackground = true)
@Composable
private fun ${feature}ScreenContentPreview() {
    PreviewRoot {
        ${feature}Screen(
            uiState = UiState.Content(${feature}Content(userName = "katachi")),
            onRefresh = {},
            onNavigateUp = {},
        )
    }
}

@Preview(showBackground = true)
@Composable
private fun ${feature}ScreenLoadingPreview() {
    PreviewRoot {
        ${feature}Screen(
            uiState = UiState.Loading,
            onRefresh = {},
            onNavigateUp = {},
        )
    }
}

package com.example.sample.feature.${feature}

import androidx.lifecycle.ViewModel
import com.example.sample.data.user.UserRepository
import com.example.sample.data.user.UserRepositoryImpl
import com.example.sample.ui.core.UiState
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow

/** What [${feature}Screen] draws once it has something to draw. */
internal data class ${feature}Content(
    val userName: String,
)

/** State holder of [${feature}Screen]. */
internal class ${feature}ViewModel(
    private val userRepository: UserRepository = UserRepositoryImpl(),
) : ViewModel() {
    private val mutableUiState = MutableStateFlow<UiState<${feature}Content>>(UiState.Loading)

    /** State of the ${feature} screen, collected by the composable. */
    val uiState: StateFlow<UiState<${feature}Content>> = mutableUiState.asStateFlow()

    init {
        refresh()
    }

    /** Reads the current user again and republishes the screen state. */
    fun refresh() {
        mutableUiState.value = UiState.Content(
            ${feature}Content(userName = userRepository.currentUserName()),
        )
    }
}

